"""Checks closed forms generated by unrol_radial.py (--format code) against direct quadrature.

Each case is evaluated as the library did before f6f4db6: the base integrals Q_00N, G1A, G1B and
H2 are computed as in the removed radial_gen.part1 (ported here, in high precision), multiplied
by the generated coefficients, and compared with the radial integral as the library defines it,

    G(k, i, j) = int_0^inf r^k exp(-u r^2 - a (r - A)^2 - b (r - B)^2) K_i(2aAr) K_j(2bBr) dr,

with K_l(z) = exp(-z) M_l(z) and M_l the modified spherical Bessel function of the first kind.
In exact arithmetic every case should agree to the working precision; run it with
--digits 16 to see the cancellation that made the closed forms inaccurate in double precision.

usage: python unrol_radial.py > cases.txt
       python check_closed_forms.py cases.txt [--digits 40] [u a b A B]
Requires sympy and mpmath.
"""

import argparse
import re

import mpmath as mp
from sympy import Symbol, lambdify, sympify


def base_integrals(u, a, b, A, B, nmax):
    """Base integrals of a primitive triple, as in radial_gen.part1: values[N - 2] = Q_00N for
    N = 2, ..., nmax, and G1A, G1B, H2. The F (even N) and G (odd N) integrals are sums over
    X1 = exp(p P1^2 - aA^2 - bB^2) / (16 x y) and X2 (likewise with P2), whose terms alternate
    in sign: this is where precision is lost when X1 ~ X2 (small x = aA)."""
    p = u + a + b
    x, y = a * A, b * B
    P1, P2 = (x + y) / p, (y - x) / p
    oP1 = 1 / P1**2
    oP2 = 0 if abs(P2) < 1e-7 else 1 / P2**2
    o_root_p = 1 / mp.sqrt(p)
    X1 = mp.exp(p * P1**2 - a * A * A - b * B * B) / (16 * x * y)
    X2 = mp.exp(p * P2**2 - a * A * A - b * B * B) / (16 * x * y)

    def dawson(t):
        return mp.sqrt(mp.pi) / 2 * mp.exp(-t * t) * mp.erfi(t)

    daw1, daw2 = X1 * dawson(mp.sqrt(p) * P1), X2 * dawson(mp.sqrt(p) * P2)
    special = {"G1A": 2 * mp.sqrt(mp.pi) * (daw1 + daw2), "G1B": 2 * mp.sqrt(mp.pi) * (daw1 - daw2),
               "H2": mp.sqrt(mp.pi) * (X1 + X2) * o_root_p}

    values = [mp.mpf(0)] * nmax
    C0 = o_root_p * mp.sqrt(mp.pi)
    P1_2k = P2_2k = mp.mpf(1)
    for n in range(1, nmax // 2 + 1):  # F_2n
        ck, dk, ek = C0, P1_2k * X1, P2_2k * X2
        val = ck * (dk - ek)
        for k in range(n - 1, 1, -1):
            ck *= 2 * k * (2 * k - 1) * (n - k - mp.mpf(0.5)) / ((2 * n - 2 * k) *
                                                                 (2 * n - 2 * k - 1) * p)
            dk *= oP1
            ek *= oP2
            val += ck * (dk - ek)
        if n > 1:
            ck *= 2 * (n - mp.mpf(1.5)) / ((2 * n - 2) * (2 * n - 3) * p)
            val += ck * (X1 - X2)
        values[2 * n - 2] = val
        P1_2k *= P1**2
        P2_2k *= P2**2
    P1_2k, P2_2k = P1, P2
    for n in range(1, (nmax - 1) // 2 + 1):  # G_2n+1
        ck, dk, ek = C0, P1_2k * X1, P2_2k * X2
        val = ck * (dk - ek)
        for k in range(n - 1, 0, -1):
            ck *= 2 * k * (2 * k + 1) * (n - k - mp.mpf(0.5)) / ((2 * n - 2 * k) *
                                                                 (2 * n - 1 - 2 * k) * p)
            dk *= oP1
            ek *= oP2
            val += ck * (dk - ek)
        values[2 * n - 1] = val
        P1_2k *= P1**2
        P2_2k *= P2**2
    return values, special


def radial(k, i, j, u, a, b, A, B):
    """G(k, i, j) by quadrature."""
    def K(l, z):
        return mp.exp(-z) * mp.sqrt(mp.pi / (2 * z)) * mp.besseli(l + mp.mpf(1) / 2, z)

    def f(r):
        return (r**k * mp.exp(-u * r * r - a * (r - A)**2 - b * (r - B)**2) *
                K(i, 2 * a * A * r) * K(j, 2 * b * B * r))
    return mp.quad(f, mp.linspace(0, 15, 61) + [mp.inf])


def main():
    parser = argparse.ArgumentParser(description=__doc__.split("\n\n")[0])
    parser.add_argument("cases", help="output of unrol_radial.py --format code")
    parser.add_argument("--digits", type=int, default=40, help="working precision (default 40)")
    parser.add_argument("triple", nargs="*", type=float, default=[1.3, 0.8, 1.1, 2.1, 2.6],
                        help="u a b A B (default 1.3 0.8 1.1 2.1 2.6)")
    args = parser.parse_args()
    u, a, b, A, B = (mp.mpf(v) for v in args.triple)

    x, y, p = Symbol("x"), Symbol("y"), Symbol("p")
    names = {"x": x, "y": y, "p": p, "x2": x**2, "y2": y**2, "p2": p**2}
    text = re.sub(r"\s+", "", open(args.cases).read())
    cases = re.findall(r"case(\d+):\{(.*?)break;\}", text)

    mp.mp.dps = args.digits
    values, special = base_integrals(u, a, b, A, B, 32)
    mp.mp.dps = 40  # the reference is always computed accurately
    worst = 0
    for label, body in cases:
        c = int(label)
        i, j, k = c // 10000, (c % 10000) // 100, c % 100
        mp.mp.dps = args.digits
        value = 0
        for coef, target, ix in re.findall(
                r"result\+?=\((.*?)\)\*(values\[(\d+)\]|G1A|G1B|H2);", body):
            cv = lambdify((x, y, p), sympify(coef, locals=names), "mpmath")(a * A, b * B, u + a + b)
            value += cv * (values[int(ix)] if ix else special[target])
        mp.mp.dps = 40
        err = abs(value / radial(k, i, j, u, a, b, A, B) - 1)
        worst = max(worst, err)
        print("Q %d %d %d  relative error %s" % (i, j, k, mp.nstr(err, 2)))
    print("%d cases, aA = %s, bB = %s, worst relative error %s"
          % (len(cases), mp.nstr(a * A, 3), mp.nstr(b * B, 3), mp.nstr(worst, 2)))


if __name__ == "__main__":
    main()
